package com.iortatechnxt.brokerverse.journal.service;

import com.iortatechnxt.brokerverse.journal.api.dto.JournalLineRequest;
import com.iortatechnxt.brokerverse.journal.domain.JournalType;
import java.time.LocalDate;
import java.util.List;

/**
 * Journal generated by the accounting engine or a period-end process.
 *
 * <p>{@code sourceModule} + {@code sourceReference} form an idempotency key: submitting the same
 * key twice returns the already posted journal instead of double posting. A correcting journal
 * (ACSL 2.9.1) carries the journal it corrects and its invoice family, see {@link #correcting}.
 *
 * @param companyId company
 * @param branchId branch
 * @param journalType system journal type
 * @param valueDate accounting date
 * @param currency header currency
 * @param narration narration
 * @param reference business reference (policy, claim, receipt no...)
 * @param sourceModule originating module, e.g. "UNDERWRITING"
 * @param sourceReference unique key of the business event
 * @param lines lines
 * @param correctsBatchId journal corrected by this one (ACSL 2.9.1), may be null
 * @param relatedInvoiceNo invoice the journal concerns, may be null
 * @param rootInvoiceNo root of the invoice family (ACSL 2.16.0), may be null
 */
public record SystemJournalRequest(
    Long companyId,
    Long branchId,
    JournalType journalType,
    LocalDate valueDate,
    String currency,
    String narration,
    String reference,
    String sourceModule,
    String sourceReference,
    List<JournalLineRequest> lines,
    Long correctsBatchId,
    String relatedInvoiceNo,
    String rootInvoiceNo) {

  /**
   * A system journal without correction or invoice links.
   *
   * @param companyId company
   * @param branchId branch
   * @param journalType system journal type
   * @param valueDate accounting date
   * @param currency header currency
   * @param narration narration
   * @param reference business reference
   * @param sourceModule originating module
   * @param sourceReference unique key of the business event
   * @param lines lines
   */
  public SystemJournalRequest(
      Long companyId,
      Long branchId,
      JournalType journalType,
      LocalDate valueDate,
      String currency,
      String narration,
      String reference,
      String sourceModule,
      String sourceReference,
      List<JournalLineRequest> lines) {
    this(
        companyId,
        branchId,
        journalType,
        valueDate,
        currency,
        narration,
        reference,
        sourceModule,
        sourceReference,
        lines,
        null,
        null,
        null);
  }

  /**
   * The same journal linked to the journal it corrects and to its invoice family.
   *
   * @param corrects id of the corrected journal
   * @param relatedInvoice invoice the correction concerns
   * @param rootInvoice root of the invoice family
   * @return linked request
   */
  public SystemJournalRequest correcting(Long corrects, String relatedInvoice, String rootInvoice) {
    return new SystemJournalRequest(
        companyId,
        branchId,
        journalType,
        valueDate,
        currency,
        narration,
        reference,
        sourceModule,
        sourceReference,
        lines,
        corrects,
        relatedInvoice,
        rootInvoice);
  }
}
